<?php $title="Edit Teacher";require "../includes/header.php";$id=(int)$_GET['id'];$q=$pdo->prepare("SELECT * FROM teachers WHERE id=?");$q->execute([$id]);$t=$q->fetch();$deps=$pdo->query("SELECT * FROM departments")->fetchAll();if(!$t)die("Not found");if($_SERVER['REQUEST_METHOD']==='POST'){$s=$pdo->prepare("UPDATE teachers SET teacher_id=?,name=?,email=?,phone=?,department_id=?,designation=? WHERE id=?");$s->execute([$_POST['teacher_id'],$_POST['name'],$_POST['email'],$_POST['phone'],$_POST['department_id'],$_POST['designation'],$id]);header("Location:index.php");exit;}?><h2>Edit Teacher</h2><div class="card p-4"><form method="post" class="row g-3"><div class="col-md-3"><label>ID</label><input name="teacher_id" value="<?=htmlspecialchars($t['teacher_id'])?>" class="form-control" required></div><div class="col-md-5"><label>Name</label><input name="name" value="<?=htmlspecialchars($t['name'])?>" class="form-control" required></div><div class="col-md-4"><label>Email</label><input name="email" value="<?=htmlspecialchars($t['email'])?>" class="form-control"></div><div class="col-md-4"><label>Phone</label><input name="phone" value="<?=htmlspecialchars($t['phone'])?>" class="form-control"></div><div class="col-md-4"><label>Department</label><select name="department_id" class="form-select"><?php foreach($deps as $d):?><option value="<?=$d['id']?>" <?=$t['department_id']==$d['id']?'selected':''?>><?=htmlspecialchars($d['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><label>Designation</label><input name="designation" value="<?=htmlspecialchars($t['designation'])?>" class="form-control"></div><div><button class="btn btn-primary">Update</button></div></form></div><?php require "../includes/footer.php";?>